begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(14);
insert into auth.users(id) values('00009030-0000-4000-8000-000000000001');
insert into public.users(id) values('00009030-0000-4000-8000-000000000001') on conflict do nothing;
insert into public.workspaces(id,name,personal,creator_id) values('00009030-0000-4000-8000-000000000010','Readiness',false,'00009030-0000-4000-8000-000000000001');
insert into public.workspace_members(ws_id,user_id,type) values('00009030-0000-4000-8000-000000000010','00009030-0000-4000-8000-000000000001','MEMBER') on conflict do nothing;
select ok(private.inventory_merge_schema_ready(),'Complete repair generation is ready');
select is(private.get_inventory_product_form_options('00000000-0000-0000-0000-000000000000')->>'inventoryMergeSchema','aliases-v1','Current baseline RPC identifies aliases even for an empty workspace');
select ok(not has_function_privilege('authenticated','private.inventory_merge_schema_ready()','EXECUTE'),'Clients cannot bypass API readiness authorization');
alter view private.inventory_active_warehouses rename to inventory_active_warehouses_unavailable;
select ok(not private.inventory_merge_schema_ready(),'Missing active view blocks readiness');
select is(private.get_inventory_product_form_options('00000000-0000-0000-0000-000000000000')->>'inventoryMergeSchema','aliases-v1','Missing view still witnesses alias schema and forbids legacy fallback');
select throws_ok($$select private.preview_inventory_merge('00000000-0000-0000-0000-000000000000','product',gen_random_uuid(),gen_random_uuid())$$,'55000',null,'SQL preview fails closed before view rollout');
select throws_ok($$select private.apply_inventory_merge('00009030-0000-4000-8000-000000000010','product',gen_random_uuid(),gen_random_uuid(),'unused','target','target','00009030-0000-4000-8000-000000000001')$$,'55000',null,'SQL apply refuses partially deployed schema after membership check');
alter view private.inventory_active_warehouses_unavailable rename to inventory_active_warehouses;
alter table private.inventory_products disable trigger inventory_identity_writer;
select ok(not private.inventory_merge_schema_ready(),'Partial reference guard installation blocks readiness');
select throws_ok($$select private.preview_inventory_merge('00000000-0000-0000-0000-000000000000','warehouse',gen_random_uuid(),gen_random_uuid())$$,'55000',null,'Partial schema cannot preview a new merge');
alter table private.inventory_products enable trigger inventory_identity_writer;
alter table private.inventory_products disable trigger inventory_merged_reference_guard;
select ok(not private.inventory_merge_schema_ready(),'Missing stale-reference guard blocks readiness');
alter table private.inventory_products enable trigger inventory_merged_reference_guard;
select ok(private.inventory_merge_schema_ready(),'Alias guard restoration restores readiness');
select ok(private.inventory_merge_schema_ready(),'Readiness restored after all prerequisites present');
select ok(has_function_privilege('service_role','private.inventory_merge_schema_ready()','EXECUTE'),'Authorized service API can inspect readiness');
select ok(private.get_inventory_product_form_options('00000000-0000-0000-0000-000000000000')->'warehouses'='[]'::jsonb,'Baseline RPC remains available with valid empty warehouse payload');
select * from finish();
rollback;
